internal sealed class NextHttpHandler:HttpMessageHandler {internal readonly Queue<byte[]> Responses=new Queue<byte[]>();internal readonly Queue<HttpResponseMessage> Messages=new Queue<HttpResponseMessage>();protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();if(Messages.Count>0)return Task.FromResult(Messages.Dequeue());return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(Responses.Dequeue())});}}
