  queue.Enqueue("{\"items\":[{\"id\":\"day\",\"summary\":\"Journée\",\"start\":{\"date\":\"2026-10-22\"},\"end\":{\"date\":\"2026-10-23\"}},{\"id\":\"cancel\",\"status\":\"cancelled\"}]}");
  var events=await calendar.Events("a@b",new DateTime(2026,10,1),new DateTime(2026,11,1),CancellationToken.None);if(events.Count!=1||GoogleCalendarClient.LocalStart(events[0])!=new DateTime(2026,10,22)||!calls.Last().Contains("a%40b"))throw new Exception("Liste et conversion des événements");
