  queue.Enqueue("{}");events[0].etag="\"revision1\"";await calendar.Save("a@b",events[0],"Modifié","Description",new DateTime(2026,10,22,14,0,0),new DateTime(2026,10,22,15,0,0),false,CancellationToken.None);if(!calls.Last().StartsWith("PATCH ")||!calls.Last().Contains("revision1")||!payloads.Last().Contains("dateTime"))throw new Exception("Modification conditionnelle");
