   handler.Responses.Enqueue(Encoding.UTF8.GetBytes(manifest));var release=await updates.Check("https://updates.example/version.json",CancellationToken.None);handler.Responses.Enqueue(bytes);string target=Path.Combine(folder,"verified.zip");await updates.Download(release,target,CancellationToken.None);if(File.ReadAllText(target)!="archive-exemple")throw new Exception("Téléchargement vérifié");
   handler.Responses.Enqueue(new byte[]{4,5});invalid=false;try{await updates.Download(release,target,CancellationToken.None);}catch(InvalidDataException){invalid=true;}if(!invalid||File.ReadAllText(target)!="archive-exemple")throw new Exception("Archive invalide écrasée");
   invalid=false;try{ApplicationUpdates.Parse(manifest.Replace("https://updates.example/app.zip","http://updates.example/app.zip"));}catch(InvalidDataException){invalid=true;}if(!invalid)throw new Exception("Mise à jour HTTP acceptée");
   var redirect=new HttpResponseMessage(HttpStatusCode.Found);redirect.Headers.Location=new Uri("https://cdn.example/release.json");handler.Messages.Enqueue(redirect);handler.Responses.Enqueue(Encoding.UTF8.GetBytes(manifest));await updates.Check("https://updates.example/redir",CancellationToken.None);var downgrade=new HttpResponseMessage(HttpStatusCode.Found);downgrade.Headers.Location=new Uri("http://bad.example/release.json");handler.Messages.Enqueue(downgrade);invalid=false;try{await updates.Check("https://updates.example/redir",CancellationToken.None);}catch(InvalidDataException){invalid=true;}if(!invalid)throw new Exception("Redirection HTTP acceptée");using(var cancel=new CancellationTokenSource()){cancel.Cancel();invalid=false;try{await updates.Download(release,target,cancel.Token);}catch(OperationCanceledException){invalid=true;}if(!invalid)throw new Exception("Annulation ignorée");}
  }
