 internal static void Pdf(string file){
  string[] objects={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Count 1 /Kids [3 0 R] >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 400 300] /Contents 4 0 R >>","<< /Length 31 >>\nstream\n0.9 0.5 0 rg 40 180 200 80 re f\nendstream"};var text=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>();for(int i=0;i<objects.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(text.ToString()));text.Append((i+1)+" 0 obj\n"+objects[i]+"\nendobj\n");}int xref=text.Length;text.Append("xref\n0 5\n0000000000 65535 f \n");foreach(int offset in offsets)text.Append(offset.ToString("0000000000")+" 00000 n \n");text.Append("trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF");File.WriteAllText(file,text.ToString(),Encoding.ASCII);
 }
}
